let aigs_incidents = toscalar(
    SecurityIncident
    | where TimeGenerated > {TimeRange:start}
    | where Title has_any ('AIGS','AI Governance','Content Filter','RAI Policy','Copilot','Agent Config')
    | count
);
let aigs_alerts = toscalar(
    SecurityAlert
    | where TimeGenerated > {TimeRange:start}
    | where AlertName has_any ('AIGS','AI Governance','Content Filter','Copilot','Agent','RAI')
    | count
);
union
    (print Metric='Active AIGS Incidents', Value=tolong(aigs_incidents), SortOrder=1),
    (print Metric='Active AIGS Alerts', Value=tolong(aigs_alerts), SortOrder=2),
                  (print Metric='Modules Active', Value=long(3), SortOrder=3),
    (print Metric='Modules Planned', Value=long(4), SortOrder=4),
    (print Metric='Controls Monitored', Value=long(11), SortOrder=5),
    (print Metric='Frameworks Mapped', Value=long(2), SortOrder=6)
| order by SortOrder asc
| project Metric, Value

// CONTROL: AIGS-CD001  MODULE: A — Azure OpenAI / Foundry
// ASIM: imAuditEvent — native  (AzureActivity maps natively to _Im_AuditEvent)
// Detects ARM management-plane writes to Azure OpenAI RAI (content filter) policies.
// Source: AzureActivity — built-in connector, no additional deployment required.
// Watchlist: AIGS_ContentFilterPolicies (baseline authority for approved policy names)
AzureActivity
| where TimeGenerated > {TimeRange:start}
| where OperationNameValue =~ 'Microsoft.CognitiveServices/accounts/raiPolicies/write'
| project
    TimeGenerated,
    ResourceGroup,
    Resource,
    Caller,
    CallerIpAddress,
    OperationNameValue,
    ActivityStatus,
    ActivitySubstatus,
    Properties=tostring(Properties)
| sort by TimeGenerated desc

// HUNT: AIGS-Hunt-AzureOpenAIRAIChanges  MODULE: A — Azure OpenAI / Foundry
// ASIM: imAuditEvent — native
// Returns all raiPolicy write/delete events for historical investigation and AIGS-CD001 baseline seeding.
// Workbook view: raw events. Run full hunt file for watchlist-joined analysis.
let RaiPolicyOps = dynamic([
    'microsoft.cognitiveservices/accounts/raipolicies/write',
    'microsoft.cognitiveservices/accounts/raipolicies/delete'
]);
AzureActivity
| where TimeGenerated > {TimeRange:start}
| where tolower(OperationNameValue) in (RaiPolicyOps)
| extend
    AccountName   = tostring(extract(@'/accounts/([^/]+)', 1, tolower(_ResourceId))),
    PolicyTarget  = tostring(extract(@'/raipolicies/([^/]+)', 1, tolower(_ResourceId))),
    OperationType = iff(tolower(OperationNameValue) has 'delete', 'Delete', 'Write')
| extend RiskSignal = case(
    OperationType == 'Delete' and ActivityStatusValue =~ 'Success', '🔴 HIGH — Successful delete; validate policy still present',
    OperationType == 'Delete',                                       '🟡 MEDIUM — Failed delete attempt; review caller intent',
    OperationType == 'Write' and ActivityStatusValue =~ 'Success',  '🟡 MEDIUM — Successful write; validate policy values unchanged',
    '🟢 LOW — Review')
| project TimeGenerated, RiskSignal, OperationType, ActivityStatusValue,
    AccountName, PolicyTarget, Caller, CallerIpAddress, SubscriptionId, ResourceGroup
| order by TimeGenerated desc

// HUNT: AIGS-Hunt-AIModelDeploymentChanges  MODULE: E — Azure General
// ASIM: imAuditEvent — native
// Returns successful CognitiveServices deployments/write events for investigation.
// Workbook view: raw deployment events. Run full hunt file for watchlist-joined analysis.
// Note: AIGS-AM001 analytic rule has not been authored — no automated alert fires.
// Note: This hunt also surfaces Azure OpenAI/Foundry deployment activity (AzureActivity is shared).
AzureActivity
| where TimeGenerated > {TimeRange:start}
| where tolower(OperationNameValue) == 'microsoft.cognitiveservices/accounts/deployments/write'
| where ActivityStatusValue =~ 'Success'
| extend
    AccountName    = tostring(extract(@'/accounts/([^/]+)', 1, tolower(_ResourceId))),
    DeploymentName = tostring(extract(@'/deployments/([^/]+)', 1, tolower(_ResourceId)))
| project TimeGenerated, AccountName, DeploymentName, Caller, CallerIpAddress,
    OperationNameValue, ActivityStatusValue, SubscriptionId, ResourceGroup, _ResourceId, CorrelationId
| order by TimeGenerated desc

// Platform Health - module status using isfuzzy=true for optional tables.
// Tables absent from workspace return 0 and surface as Not Configured.
// isfuzzy=true: missing table legs are silently skipped; no query errors.
let modA = toscalar(
    AzureActivity | where TimeGenerated > ago(7d)
    | where OperationNameValue has 'cognitiveservices' | count
);
let modB = toscalar(
    union isfuzzy=true
                      (AgentsInfo | where Timestamp > ago(7d) | summarize n=count()),
        (print n=long(0))
    | summarize max(n)
);
let modC = toscalar(
    union isfuzzy=true
        (CopilotActivity | where Workload != 'SecurityCopilot' | where TimeGenerated > ago(7d) | summarize n=count()),
        (print n=long(0))
    | summarize max(n)
);
let modD = toscalar(
    union isfuzzy=true
        (CloudAppEvents | where TimeGenerated > ago(7d) | summarize n=count()),
        (print n=long(0))
    | summarize max(n)
);
let modE = toscalar(
    AzureActivity | where TimeGenerated > ago(7d)
    | where OperationNameValue has 'cognitiveservices'
          and OperationNameValue has 'deployments'
    | count
);
let modF = toscalar(
    union isfuzzy=true
        (OfficeActivity | where OfficeWorkload == 'Purview' | where TimeGenerated > ago(7d) | summarize n=count()),
        (print n=long(0))
    | summarize max(n)
);
let modG = toscalar(
    union isfuzzy=true
        (CopilotActivity | where Workload == 'SecurityCopilot' | where TimeGenerated > ago(7d) | summarize n=count()),
        (print n=long(0))
    | summarize max(n)
);
datatable(
    Module:string, Label:string, Maturity:string, DefaultEnabled:string,
    PrimaryTable:string, RequiredConnector:string, ControlIDs:string, ASIMLabel:string
)[
    'A','Azure OpenAI / Foundry','GA','Enabled',
        'AzureActivity','Azure Activity (built-in)','AIGS-CD001 | AIGS-CD005','imAuditEvent - native',
    'B','Agent 365 [Preview]','Preview','Enabled',
        'AgentsInfo','Microsoft Defender XDR','AIGS-PA001 | AIGS-CD002','N/A - Defender XDR inventory (no ASIM)',
    'C','M365 Copilot [Preview]','Preview','Enabled',
        'CopilotActivity','Microsoft Copilot Data Connector','AIGS-CD003 | AIGS-Hunt-CopilotAgentModelInventory','N/A - direct-KQL, non-ASIM',
    'D','Defender XDR [Preview]','Preview','Enabled',
        'CloudAppEvents','Microsoft Defender XDR','AIGS-CD004','N/A - cloud app events (no applicable ASIM schema)',
    'E','Azure General','GA','Enabled',
        'AzureActivity','Azure Activity (built-in)','AIGS-AM001','imAuditEvent - native',
    'F','Microsoft Purview [Preview]','Preview','Enabled',
        'OfficeActivity','Office 365 connector','AIGS-AM002','imAuditEvent - partial',
    'G','Security Copilot [Preview]','Preview','Disabled (default)',
        'CopilotActivity','Copilot Data Connector + UAL opt-in','AIGS-RU001','Custom: AIGS_CopilotActivity_Normalized (NOT ASIM)'
]
| extend EventCount7d = case(
    Module == 'A', modA, Module == 'B', modB, Module == 'C', modC,
    Module == 'D', modD, Module == 'E', modE, Module == 'F', modF,
    Module == 'G', modG, long(0)
)
| extend Status = case(
    Module == 'G',               'Disabled - enableSecurityCopilotModule = false (default)',
    Module == 'A' and modA > 0,  'Healthy - Azure OpenAI governance events detected',
    Module == 'A',               'Degraded - AzureActivity present; no AI governance events (7d)',
    Module == 'B' and modB > 0,  'Healthy',
    Module == 'B',               'Not Configured - Microsoft Defender XDR connector required',
    Module == 'C' and modC > 0,  'Healthy - Copilot agent/model events detected',
    Module == 'C',               'Not Configured - Microsoft Copilot Data Connector required',
    Module == 'D' and modD > 0,  'Healthy',
    Module == 'D',               'Not Configured - Microsoft Defender XDR connector required',
    Module == 'E' and modE > 0,  'Healthy - Model deployment events detected',
    Module == 'E',               'Degraded - AzureActivity present; no model deployment events (7d)',
    Module == 'F' and modF > 0,  'Healthy - Purview AI Hub events detected',
    Module == 'F',               'Not Configured - No Purview AI Hub events (7d)',
    'Unknown'
)
| where '{ModuleFilter}' == 'All' or Module == '{ModuleFilter}'
| where '{MaturityFilter}' == 'All' or Maturity == '{MaturityFilter}'
| project Module, Label, Status, EventCount7d, Maturity, DefaultEnabled,
          ControlIDs, ASIMLabel, RequiredConnector
| sort by Module asc
